import random,math,json
def sig(x): return 1.0/(1.0+math.exp(-x))
def run(w_eff):
 vals={'naive':[],'w':[],'g':[],'p':[]}
 for seed in range(30):
  r=random.Random(202608080+seed); ds=[r.gauss(-.15,1)+r.gauss(0,.25) for _ in range(3000)]
  m={}
  for g in (0,1):
   for w in (0,1):
    for p in (0,1):
     m[g,w,p]=sum(sig(d+.55*g+w_eff*w+.50*p+.18*g*p) for d in ds)/len(ds)
  vals['naive'].append(m[1,1,1]-m[0,0,0])
  vals['w'].append(sum(m[g,1,p]-m[g,0,p] for g in (0,1) for p in (0,1))/4)
  vals['g'].append(sum(m[1,w,p]-m[0,w,p] for w in (0,1) for p in (0,1))/4)
  vals['p'].append(sum(m[g,w,1]-m[g,w,0] for g in (0,1) for w in (0,1))/4)
 return {k:sum(v)/len(v) for k,v in vals.items()}
print(json.dumps({'confounded_null':run(0.0),'true_workspace':run(0.45)},sort_keys=True))
